import { createRouter, createWebHistory } from "vue-router";
import UserLogin from "@/components/UserLogin.vue";
import UserPage from "@/views/UserPage.vue"; // 用户页面
// import UserDashboard from "@/views/UserDashboard.vue"; // 仪表盘页面
// import UserProfile from "@/views/UserProfile.vue"; // 个人资料页面
// import UserSettings from "@/views/UserSettings.vue"; // 设置页面

const routes = [
  {
    path: "/",
    redirect: "/login", // 默认重定向到登录页
  },
  {
    path: "/login",
    name: "Login",
    component: UserLogin,
  },
  {
    path: "/user",
    name: "User",
    component: UserPage,
    children: [
      {
        path: "dashboard",
        component: Dashboard,
      },
      {
        path: "profile",
        component: Profile,
      },
      {
        path: "settings",
        component: Settings,
      },
    ],
  },
];

const router = createRouter({
  history: createWebHistory(),
  routes,
});

export default router;
